    <script>
        // Dynamic data management system
        if (typeof getChatMessages != "function") {
            window.getChatMessages = async () => [{ data: {} }];
        }
        if (typeof getCurrentMessageId != "function") {
            window.getCurrentMessageId = () => 0;
        }

        let characterData = {};

        // Sleep function for polling
        function sleep(ms) {
            return new Promise(resolve => setTimeout(resolve, ms));
        }

        // Check if data is valid (has required structure)
        function isValidData(data) {
            return data && (data.指针 || data.世界 || data.主角 || data.角色);
        }

        // Function to safely get nested object properties
        function safeGet(obj, path, defaultValue = '') {
            return path.split('.').reduce((current, key) => {
                return current && current[key] !== undefined ? current[key] : defaultValue;
            }, obj);
        }

        // Update progress bars with proper percentage calculation
        function updateProgressBar(barId, value, max = 100) {
            const bar = document.getElementById(barId);
            if (bar) {
                const percentage = Math.max(0, Math.min(100, (value / max) * 100));
                bar.style.width = `${percentage}%`;
            }
        }

        // Initialize and try to load dynamic data (简化版，逻辑与 merged_terminal.html 保持一致)
        async function initDisplay() {
            let attempts = 0;
            const maxAttempts = 60; // 最多尝试60次 (约1分钟)

            console.log('🔍 开始轮询数据...');

            while (attempts < maxAttempts) {
                try {
                    attempts++;

                    const msg = await getChatMessages(getCurrentMessageId());
                    const data = msg[0].data || {};
                    const potentialData = data.stat_data || data.display_data || data;

                    // 检查数据是否有效
                    if (isValidData(potentialData)) {
                        characterData = potentialData;
                        console.log(`✅ 第 ${attempts} 次尝试成功，获取到有效数据`);

                        // 获取到数据后等待500ms再渲染
                        await sleep(500);

                        updateDynamicUI();
                        window.uiInitialized = true;
                        return; // 成功获取数据，退出循环
                    }
                } catch (error) {
                    // 静默处理错误，避免日志污染
                }

                // 等待1秒后重试
                await sleep(1000);
            }

            console.warn('⚠️ 轮询超时，未获取到有效数据');
        }

