            </div>
        </main>

        <footer class="dashboard-footer">
            <div class="footer-accordion">
                <details open>
                    <summary>行动选项</summary>
                    <div class="options-list">
                        <button class="option-button" id="action1">加载中...</button>
                        <button class="option-button" id="action2">加载中...</button>
                        <button class="option-button" style="color:#fca5a5;" id="action3">加载中...</button>
                    </div>
                </details>
            </div>
            <div class="footer-accordion">
                <details open>
                    <summary>剧情推进</summary>
                    <div class="options-list">
                        <button class="option-button" id="plot1">加载中...</button>
                        <button class="option-button" id="plot2">加载中...</button>
                        <button class="option-button" id="plot3">加载中...</button>
                    </div>
                </details>
            </div>
        </footer>
    </div>

    <script>
        // Dynamic data management system
        if (typeof getChatMessages != "function") {
            window.getChatMessages = async () => [{ data: {} }];
        }
        if (typeof getCurrentMessageId != "function") {
            window.getCurrentMessageId = () => 0;
        }

        let characterData = {};

        // Sleep function for polling
        function sleep(ms) {
            return new Promise(resolve => setTimeout(resolve, ms));
        }

        // Check if data is valid (has required structure)
        function isValidData(data) {
            return data && (data.指针 || data.世界 || data.主角 || data.角色);
        }

        // Function to safely get nested object properties
        function safeGet(obj, path, defaultValue = '') {
            return path.split('.').reduce((current, key) => {
                return current && current[key] !== undefined ? current[key] : defaultValue;
            }, obj);
        }

        // Update progress bars with proper percentage calculation
        function updateProgressBar(barId, value, max = 100) {
            const bar = document.getElementById(barId);
            if (bar) {
                const percentage = Math.max(0, Math.min(100, (value / max) * 100));
                bar.style.width = `${percentage}%`;
            }
        }

        // Initialize and try to load dynamic data (简化版，逻辑与 merged_terminal.html 保持一致)
        async function initDisplay() {
            let attempts = 0;
            const maxAttempts = 60; // 最多尝试60次 (约1分钟)

            console.log('🔍 开始轮询数据...');

            while (attempts < maxAttempts) {
                try {
                    attempts++;

                    const msg = await getChatMessages(getCurrentMessageId());
                    const data = msg[0].data || {};
                    const potentialData = data.stat_data || data.display_data || data;

                    // 检查数据是否有效
                    if (isValidData(potentialData)) {
                        characterData = potentialData;
                        console.log(`✅ 第 ${attempts} 次尝试成功，获取到有效数据`);

                        // 获取到数据后等待500ms再渲染
                        await sleep(500);

                        updateDynamicUI();
                        window.uiInitialized = true;
                        return; // 成功获取数据，退出循环
                    }
                } catch (error) {
                    // 静默处理错误，避免日志污染
                }

                // 等待1秒后重试
                await sleep(1000);
            }

            console.warn('⚠️ 轮询超时，未获取到有效数据');
        }

        // 完全重写的数据更新函数，与 merged_terminal.html 保持一致
        function updateDynamicUI() {
            if (!characterData || Object.keys(characterData).length === 0) {
                console.log('No character data available');
                return;
            }

            console.log('Updating UI with character data:', characterData);

            // 更新世界信息
            if (characterData.世界) {
                const worldData = characterData.世界;
                document.getElementById('system-time').textContent = (worldData.时间 && Array.isArray(worldData.时间)) ? worldData.时间[0] : worldData.时间 || '';
                document.getElementById('current-location').textContent = (worldData.坐标 && Array.isArray(worldData.坐标)) ? worldData.坐标[0] : worldData.坐标 || '';
                document.getElementById('current-mission').textContent = (worldData.任务 && Array.isArray(worldData.任务)) ? worldData.任务[0] : worldData.任务 || '';
                document.getElementById('meeting-notes').textContent = (worldData.会议纪要 && Array.isArray(worldData.会议纪要)) ? worldData.会议纪要[0] : worldData.会议纪要 || '';
                document.getElementById('news1-date').textContent = (worldData.新闻1日期 && Array.isArray(worldData.新闻1日期)) ? worldData.新闻1日期[0] : worldData.新闻1日期 || '';
                document.getElementById('news1-title').textContent = (worldData.新闻1标题 && Array.isArray(worldData.新闻1标题)) ? worldData.新闻1标题[0] : worldData.新闻1标题 || '';
                document.getElementById('news2-date').textContent = (worldData.新闻2日期 && Array.isArray(worldData.新闻2日期)) ? worldData.新闻2日期[0] : worldData.新闻2日期 || '';
                document.getElementById('news2-title').textContent = (worldData.新闻2标题 && Array.isArray(worldData.新闻2标题)) ? worldData.新闻2标题[0] : worldData.新闻2标题 || '';
            }

            // 更新主角信息
            if (characterData.主角) {
                const protagonistData = characterData.主角;
                document.getElementById('protagonist-position').textContent = (protagonistData.职位 && Array.isArray(protagonistData.职位)) ? protagonistData.职位[0] : protagonistData.职位 || '';
                document.getElementById('protagonist-job').textContent = (protagonistData.工作 && Array.isArray(protagonistData.工作)) ? protagonistData.工作[0] : protagonistData.工作 || '';
                document.getElementById('protagonist-goal').textContent = (protagonistData.目标 && Array.isArray(protagonistData.目标)) ? protagonistData.目标[0] : protagonistData.目标 || '';
            }

            // 更新交互按钮
            if (characterData.交互) {
                const interactionData = characterData.交互;
                document.getElementById('action1').textContent = (interactionData.行动1 && Array.isArray(interactionData.行动1)) ? interactionData.行动1[0] : interactionData.行动1 || '';
                document.getElementById('action2').textContent = (interactionData.行动2 && Array.isArray(interactionData.行动2)) ? interactionData.行动2[0] : interactionData.行动2 || '';
                document.getElementById('action3').textContent = (interactionData.行动3 && Array.isArray(interactionData.行动3)) ? interactionData.行动3[0] : interactionData.行动3 || '';
                document.getElementById('plot1').textContent = (interactionData.剧情1 && Array.isArray(interactionData.剧情1)) ? interactionData.剧情1[0] : interactionData.剧情1 || '';
                document.getElementById('plot2').textContent = (interactionData.剧情2 && Array.isArray(interactionData.剧情2)) ? interactionData.剧情2[0] : interactionData.剧情2 || '';
                document.getElementById('plot3').textContent = (interactionData.剧情3 && Array.isArray(interactionData.剧情3)) ? interactionData.剧情3[0] : interactionData.剧情3 || '';
            }

            // 更新焦点角色（动态指针系统）
            if (characterData.指针 && characterData.角色) {
                const pointerData = characterData.指针;
                const focusCharName = (pointerData.焦点 && Array.isArray(pointerData.焦点)) ? pointerData.焦点[0] : pointerData.焦点;
                const opp1CharName = (pointerData.机遇1 && Array.isArray(pointerData.机遇1)) ? pointerData.机遇1[0] : pointerData.机遇1;
                const opp2CharName = (pointerData.机遇2 && Array.isArray(pointerData.机遇2)) ? pointerData.机遇2[0] : pointerData.机遇2;

                console.log('Focus character:', focusCharName);
                console.log('Opportunity characters:', opp1CharName, opp2CharName);

                // 更新焦点角色
                if (focusCharName && characterData.角色[focusCharName]) {
                    const focusChar = characterData.角色[focusCharName];
                    const charName = (focusChar.名称 && Array.isArray(focusChar.名称)) ? focusChar.名称[0] : focusChar.名称;
                    const charPosition = (focusChar.职位 && Array.isArray(focusChar.职位)) ? focusChar.职位[0] : focusChar.职位;
                    document.getElementById('focus-character-name').textContent = `${charName} - ${charPosition}`;

                    const affinity = (focusChar.好感 && Array.isArray(focusChar.好感)) ? parseInt(focusChar.好感[0]) || 0 : parseInt(focusChar.好感) || 0;
                    const desire = (focusChar.欲念 && Array.isArray(focusChar.欲念)) ? parseInt(focusChar.欲念[0]) || 0 : parseInt(focusChar.欲念) || 0;

                    document.getElementById('focus-affinity-value').textContent = affinity;
                    document.getElementById('focus-desire-value').textContent = desire;
                    updateProgressBar('focus-affinity-bar', affinity);
                    updateProgressBar('focus-desire-bar', desire);

                    document.getElementById('focus-inner-thought').textContent = (focusChar.心语 && Array.isArray(focusChar.心语)) ? focusChar.心语[0] : focusChar.心语 || '';
                    document.getElementById('focus-breast').textContent = (focusChar.生理乳房 && Array.isArray(focusChar.生理乳房)) ? focusChar.生理乳房[0] : focusChar.生理乳房 || '';
                    document.getElementById('focus-private').textContent = (focusChar.生理私密 && Array.isArray(focusChar.生理私密)) ? focusChar.生理私密[0] : focusChar.生理私密 || '';
                    document.getElementById('focus-clothing').textContent = (focusChar.生理穿着 && Array.isArray(focusChar.生理穿着)) ? focusChar.生理穿着[0] : focusChar.生理穿着 || '';
                    document.getElementById('focus-posture').textContent = (focusChar.生理姿态 && Array.isArray(focusChar.生理姿态)) ? focusChar.生理姿态[0] : focusChar.生理姿态 || '';
                }

                // 更新机遇角色1
                if (opp1CharName && characterData.角色[opp1CharName]) {
                    const opp1Char = characterData.角色[opp1CharName];
                    const charName = (opp1Char.名称 && Array.isArray(opp1Char.名称)) ? opp1Char.名称[0] : opp1Char.名称;
                    const charPosition = (opp1Char.职位 && Array.isArray(opp1Char.职位)) ? opp1Char.职位[0] : opp1Char.职位;
                    document.getElementById('opportunity1-name').textContent = `${charName} - ${charPosition}`;
                    document.getElementById('opportunity1-summary').textContent = (opp1Char.简介 && Array.isArray(opp1Char.简介)) ? opp1Char.简介[0] : opp1Char.简介 || '';
                    document.getElementById('opportunity1-appearance').textContent = (opp1Char.容貌 && Array.isArray(opp1Char.容貌)) ? opp1Char.容貌[0] : opp1Char.容貌 || '';
                    document.getElementById('opportunity1-breakthrough').textContent = (opp1Char.突破口 && Array.isArray(opp1Char.突破口)) ? opp1Char.突破口[0] : opp1Char.突破口 || '';
                }

                // 更新机遇角色2
                if (opp2CharName && characterData.角色[opp2CharName]) {
                    const opp2Char = characterData.角色[opp2CharName];
                    const charName = (opp2Char.名称 && Array.isArray(opp2Char.名称)) ? opp2Char.名称[0] : opp2Char.名称;
                    const charPosition = (opp2Char.职位 && Array.isArray(opp2Char.职位)) ? opp2Char.职位[0] : opp2Char.职位;
                    document.getElementById('opportunity2-name').textContent = `${charName} - ${charPosition}`;
                    document.getElementById('opportunity2-summary').textContent = (opp2Char.简介 && Array.isArray(opp2Char.简介)) ? opp2Char.简介[0] : opp2Char.简介 || '';
                    document.getElementById('opportunity2-appearance').textContent = (opp2Char.容貌 && Array.isArray(opp2Char.容貌)) ? opp2Char.容貌[0] : opp2Char.容貌 || '';
                    document.getElementById('opportunity2-breakthrough').textContent = (opp2Char.突破口 && Array.isArray(opp2Char.突破口)) ? opp2Char.突破口[0] : opp2Char.突破口 || '';
                }
            }

            console.log('✅ UI update completed successfully');
        }

        // Enhanced button click handling
        document.addEventListener('DOMContentLoaded', function() {
            console.log('🚀 DOM加载完成，启动数据轮询...');
            initDisplay();

            const choiceButtons = document.querySelectorAll('.option-button');

            function handleChoiceClick(optionText) {
                const requestText = optionText.trim();
                const command = `/send ${requestText} | /trigger`;

                try {
                    if (typeof window.triggerSlash === 'function') {
                        window.triggerSlash(command);
                        return;
                    } else if (window.parent && typeof window.parent.triggerSlash === 'function') {
                        window.parent.triggerSlash(command);
                        return;
                    }
                } catch (e) {
                    console.error('调用 triggerSlash 时出错:', e);
                }

                console.warn('triggerSlash 函数未找到，正在尝试后备方法...');
                try {
                    const parentDoc = window.parent.document;
                    const textbox = parentDoc.getElementById('send_textarea');
                    const sendButton = parentDoc.getElementById('send_but');

                    if (textbox && sendButton) {
                        const lastValue = textbox.value;
                        textbox.value = requestText;
                        textbox.dispatchEvent(new Event('input', { bubbles: true }));
                        sendButton.click();
                    } else {
                        console.error('后备方法失败：在父文档中未找到输入框或发送按钮。');
                    }
                } catch (e) {
                    console.error('在执行后备DOM操作时出错:', e);
                }
            }

            choiceButtons.forEach(button => {
                button.addEventListener('click', (event) => {
                    const buttonText = event.target.textContent;
                    handleChoiceClick(buttonText);
                });
            });
        });

        // Resize observer for parent frame
        try {
            const ro = new ResizeObserver(entries => {
                const height = document.body.scrollHeight;
                if (window.parent) {
                    window.parent.postMessage({
                        'type': 'resize',
                        'height': height
                    }, '*');
                }
            });
            ro.observe(document.body);
        } catch (e) {
            console.error("ResizeObserver failed:", e);
        }

        // Expose functions for external access
        window.updateDynamicUI = updateDynamicUI;
        window.setCharacterData = function(data) {
            characterData = data;
            updateDynamicUI();
        };

        // Listen for data updates from parent frame
        window.addEventListener('message', function(event) {
            if (event.data && event.data.type === 'updatecharacterData') {
                const newData = event.data.data;
                if (isValidData(newData)) {
                    characterData = newData;
                    updateDynamicUI();
                    window.uiInitialized = true;
                }
            }
        });

    </script>
</body>
</html>
